package io.knowledgebrain.activity;
import java.nio.file.*;import java.time.*;import java.util.*;import javax.sql.DataSource;import com.zaxxer.hikari.*;import org.flywaydb.core.Flyway;import org.springframework.context.annotation.*;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.boot.health.contributor.*;import io.micrometer.core.instrument.MeterRegistry;
@Configuration(proxyBeanMethods=false) @ConditionalOnProperty(name="brain.activity.persistence.enabled",havingValue="true")
final class ActivityConfiguration {
 @Bean(destroyMethod="close") HikariDataSource activityDataSource(@Value("${brain.activity.database.url}")String url,@Value("${brain.activity.database.password}")String password,MeterRegistry metrics){var c=databaseOptions(url,password,metrics);var ds=new HikariDataSource(c);try{Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();return ds;}catch(RuntimeException e){ds.close();throw e;}}
 static HikariConfig databaseOptions(String url,String password,MeterRegistry metrics){var c=new HikariConfig();c.setJdbcUrl(url);c.setUsername("brain_activity");c.setPassword(password);c.setMaximumPoolSize(3);c.setMinimumIdle(1);c.setConnectionTimeout(10000);c.setConnectionInitSql("SET statement_timeout='10s'");c.setPoolName("activity-inbox");if(metrics!=null)c.setMetricRegistry(metrics);return c;}
 @Bean ActivityStore activityStore(DataSource activityDataSource){return new ActivityStore(activityDataSource);}
 @Bean("activityReader") ActivityClickHouse reader(@Value("${brain.activity.clickhouse.origin}")String origin,@Value("${brain.activity.trust-file}")String trust)throws Exception{return new ActivityClickHouse(origin,trust,"/clickhouse-reader");}
 @Bean("activityWriter") ActivityClickHouse writer(@Value("${brain.activity.clickhouse.origin}")String origin,@Value("${brain.activity.trust-file}")String trust)throws Exception{return new ActivityClickHouse(origin,trust,"/clickhouse-projector");}
 @Bean SpaceAuthorizationClient authority(@Value("${brain.activity.space.origin}")String origin,@Value("${brain.activity.trust-file}")String trust,@Value("${brain.activity.space.key}")String key)throws Exception{return new SpaceAuthorizationClient(origin,trust,key);}
 @Bean ActivitySnapshot snapshot(@Value("${brain.activity.learning.origin}")String origin,@Value("${brain.activity.trust-file}")String trust,@Value("${brain.activity.export-key}")String key,@Value("${brain.activity.planning.origin}")String planningOrigin,@Value("${brain.activity.planning.export-key}")String planningKey,@Value("${brain.activity.content.origin}")String contentOrigin,@Value("${brain.activity.content.export-key}")String contentKey,@Value("${brain.activity.knowledge.origin}")String knowledgeOrigin,@Value("${brain.activity.knowledge.export-key}")String knowledgeKey,@Value("${brain.activity.integration.origin}")String integrationOrigin,@Value("${brain.activity.integration.export-key}")String integrationKey)throws Exception{return new ActivitySnapshot(origin,trust,key,planningOrigin,planningKey,contentOrigin,contentKey,knowledgeOrigin,knowledgeKey,integrationOrigin,integrationKey);}
 @Bean @ConditionalOnProperty(name="brain.activity.consumer.enabled",havingValue="true") ActivityConsumer consumer(ActivityStore store,@Qualifier("activityWriter")ActivityClickHouse index,ActivitySnapshot source,@Value("${brain.activity.kafka.bootstrap-servers}")String bootstrap,@Value("${brain.activity.kafka.max-poll-interval-ms:1800000}")int interval,MeterRegistry metrics)throws Exception{var options=kafka(bootstrap,"/activity-kafka","activity-learning-timeline-v1");pollInterval(options,interval);return new ActivityConsumer(store,index,source,options,metrics);}
 static void pollInterval(Properties options,int millis){if(millis<600000||millis>3600000)throw new IllegalArgumentException("Activity recovery poll interval must be 10..60 minutes");options.put("max.poll.interval.ms",Integer.toString(millis));}
 static Properties kafka(String bootstrap,String directory,String group)throws Exception{if(!group.matches("activity-[a-zA-Z0-9-]+"))throw ActivityEvent.invalid();var p=new Properties();p.put("bootstrap.servers",bootstrap);p.put("group.id",group);p.put("enable.auto.commit","false");p.put("auto.offset.reset","none");p.put("max.poll.records","20");p.put("max.poll.interval.ms","1800000");p.put("key.deserializer","org.apache.kafka.common.serialization.StringDeserializer");p.put("value.deserializer","org.apache.kafka.common.serialization.ByteArrayDeserializer");p.put("security.protocol","SSL");p.put("ssl.endpoint.identification.algorithm","HTTPS");p.put("ssl.truststore.type","PEM");p.put("ssl.truststore.certificates",Files.readString(Path.of(directory,"ca.crt")));p.put("ssl.keystore.type","PEM");p.put("ssl.keystore.certificate.chain",Files.readString(Path.of(directory,"user.crt")));p.put("ssl.keystore.key",Files.readString(Path.of(directory,"user.key")));return p;}
 @Bean HealthIndicator activityDatabaseHealthIndicator(ActivityStore store){return ()->{try{store.state();return Health.up().build();}catch(Exception e){return Health.down().build();}};}
 @Bean HealthIndicator activityStorageHealthIndicator(@Qualifier("activityReader")ActivityClickHouse reader){return ()->{try{reader.health();return Health.up().build();}catch(Exception e){return Health.down().build();}};}
 @Bean @ConditionalOnProperty(name="brain.activity.consumer.enabled",havingValue="true") HealthIndicator activityProjectionHealthIndicator(ActivityConsumer consumer){return ()->{try{return consumer.ready()?Health.up().build():Health.down().build();}catch(Exception e){return Health.down().build();}};}
}
